import{_ as e,c as o,o as n,ag as t}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Matrix-room-management","description":"","frontmatter":{"title":"Matrix-room-management"},"headers":[],"relativePath":"matrix/matrix-room-management.md","filePath":"matrix/matrix-room-management.md","lastUpdated":null}'),i={name:"matrix/matrix-room-management.md"};function s(r,a,l,m,p,c){return n(),o("div",null,[...a[0]||(a[0]=[t(`<h1 id="matrix-room-management" tabindex="-1">Matrix-room-management <a class="header-anchor" href="#matrix-room-management" aria-label="Permalink to &quot;Matrix-room-management&quot;">​</a></h1><h3 id="graphical-management" tabindex="-1">Graphical Management <a class="header-anchor" href="#graphical-management" aria-label="Permalink to &quot;Graphical Management&quot;">​</a></h3><p>For managing spaces, it is important to enable previews. If not, it will not properly display to users whenever an invite is sent.</p><h3 id="auto-join-configuration" tabindex="-1">Auto Join Configuration <a class="header-anchor" href="#auto-join-configuration" aria-label="Permalink to &quot;Auto Join Configuration&quot;">​</a></h3><p><a href="https://matrix-org.github.io/synapse/latest/usage/configuration/config_documentation.html" target="_blank" rel="noreferrer">https://matrix-org.github.io/synapse/latest/usage/configuration/config_documentation.html</a></p><p>Since this is from the main matrix documentation you need to use a passthrough (see documentation <a href="https://github.com/spantaleev/matrix-docker-ansible-deploy/blob/8051fd7012c7ce5b97b53e345dda0b61f866a689/roles/custom/matrix-synapse/defaults/main.yml#L1040" target="_blank" rel="noreferrer">here</a> <code>matrix_synapse_configuration_extension_yaml: |</code> auto_join_rooms</p><p>Users who register on this homeserver will automatically be joined to the rooms listed under this option.</p><p>By default, any room aliases included in this list will be created as a publicly joinable room when the first user registers for the homeserver. If the room already exists, make certain it is a publicly joinable room, i.e. the join rule of the room must be set to ‘public’. You can find more options relating to auto-joining rooms below.</p><p>Space aliases may also be used as Spaces are just rooms under the hood.</p><p>Example configuration:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>matrix_synapse_configuration_extension_yaml: |</span></span>
<span class="line"><span>    auto_join_rooms:</span></span>
<span class="line"><span>      - &amp;quot;#exampleroom:example.com&amp;quot;</span></span>
<span class="line"><span>      - &amp;quot;#anotherexampleroom:example.com&amp;quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>When using the ansible playbook version you can use:</p><h3 id="retention-policy-for-rooms" tabindex="-1">Retention Policy for rooms <a class="header-anchor" href="#retention-policy-for-rooms" aria-label="Permalink to &quot;Retention Policy for rooms&quot;">​</a></h3><ol><li><p>In the room, get to dev tools: <code>/devtools</code></p></li><li><p>Select &quot;Send custom timeline event&quot;</p></li></ol><h4 id="room-configuration" tabindex="-1">Room configuration <a class="header-anchor" href="#room-configuration" aria-label="Permalink to &quot;Room configuration&quot;">​</a></h4><p><a href="https://matrix-org.github.io/synapse/latest/message_retention_policies.html" target="_blank" rel="noreferrer">https://matrix-org.github.io/synapse/latest/message_retention_policies.html</a></p><p>To configure a room’s message retention policy, a room’s admin or the moderator needs to send a state event in that room with the type</p><p><code>m.room.retention</code> and the following content:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &amp;quot;max_lifetime&amp;quot;: ...</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div>`,19)])])}const h=e(i,[["render",s]]);export{d as __pageData,h as default};
